<script setup lang="ts">
import{AlertCircle,CheckCircle2,Copy,Eye,LoaderCircle,Play,Plus,Trash2,Webhook}from"lucide-vue-next";
definePageMeta({layout:"dashboard",middleware:"auth"});const{tr}=useAppPreferences();
type Hook={id:string;name:string;url:string;events:string[];status:string;lastDelivery:any};
const{data,status,refresh}=await useFetch<{webhooks:Hook[]}>("/api/webhooks");const hooks=computed(()=>data.value?.webhooks||[]);const modal=ref(false),detail=ref(false),busy=ref(false),notice=ref(""),error=ref(""),newSecret=ref(""),deliveries=ref<any[]>([]);const form=reactive({name:"",url:"",events:["message.received"]});const eventOptions=["message.received","message.sent","message.failed","whatsapp.connected","whatsapp.disconnected","contact.created","contact.updated"];
function fail(e:any){error.value=e.data?.statusMessage||tr("عملیات ناموفق بود.","Operation failed.");notice.value=""}
async function create(){busy.value=true;error.value="";try{const r=await $fetch<any>("/api/webhooks",{method:"POST",body:form});newSecret.value=r.secret;modal.value=false;notice.value=tr("وب‌هوک ساخته شد؛ Secret را همین حالا کپی کنید.","Webhook created. Copy the secret now.");await refresh()}catch(e){fail(e)}finally{busy.value=false}}
async function remove(id:string){if(!confirm(tr("این وب‌هوک حذف شود؟","Delete this webhook?")))return;try{await $fetch(`/api/webhooks/${id}`,{method:"DELETE"});notice.value=tr("وب‌هوک حذف شد.","Webhook deleted.");await refresh()}catch(e){fail(e)}}
async function test(id:string){busy.value=true;try{await $fetch(`/api/webhooks/${id}/test`,{method:"POST"});notice.value=tr("تست با پاسخ موفق تحویل شد.","Test delivered successfully.");await refresh()}catch(e){fail(e)}finally{busy.value=false}}
async function toggle(h:Hook){try{await $fetch(`/api/webhooks/${h.id}`,{method:"PATCH",body:{status:h.status==="ACTIVE"?"DISABLED":"ACTIVE"}});await refresh()}catch(e){fail(e)}}
async function showDeliveries(id:string){try{deliveries.value=(await $fetch<any>(`/api/webhooks/${id}/deliveries`)).deliveries;detail.value=true}catch(e){fail(e)}}
async function copy(value:string){await navigator.clipboard.writeText(value);notice.value=tr("کپی شد.","Copied.")}
</script>
<template><div><PageHeader :title="tr('وب‌هوک‌ها','Webhooks')" :description="tr('رویدادها را با امضای HMAC و لاگ کامل به سرویس‌های دیگر بفرستید.','Send events with HMAC signatures and delivery logs.')"><button class="btn btn-primary" @click="modal=true"><Plus :size="17"/>{{tr('وب‌هوک جدید','New webhook')}}</button></PageHeader><div v-if="notice" class="mb-4 flex gap-2 rounded-xl bg-emerald-50 p-3 text-sm font-bold text-emerald-700"><CheckCircle2 :size="18"/>{{notice}}</div><div v-if="error" class="mb-4 flex gap-2 rounded-xl bg-red-50 p-3 text-sm font-bold text-red-700"><AlertCircle :size="18"/>{{error}}</div><div v-if="newSecret" class="surface mb-5 border border-amber-300 p-5"><b>{{tr('Secret فقط یک‌بار نمایش داده می‌شود','Secret is shown only once')}}</b><div class="mt-3 flex gap-2"><code class="input overflow-hidden text-ellipsis" dir="ltr">{{newSecret}}</code><button class="icon-btn" @click="copy(newSecret)"><Copy :size="17"/></button></div><button class="mt-3 text-xs text-slate-400" @click="newSecret=''">{{tr('متوجه شدم','I saved it')}}</button></div><section class="surface overflow-hidden"><div v-if="status==='pending'" class="grid h-48 place-items-center"><LoaderCircle class="animate-spin"/></div><div v-else-if="!hooks.length" class="grid min-h-64 place-items-center p-8 text-center"><div><Webhook class="mx-auto text-slate-300" :size="48"/><p class="muted mt-3">{{tr('وب‌هوکی ساخته نشده است.','No webhooks created yet.')}}</p></div></div><template v-else><div class="hidden grid-cols-[1fr_1.5fr_1fr_.7fr_auto] gap-4 border-b bg-slate-50 px-5 py-3 text-xs font-bold text-slate-400 md:grid dark:bg-slate-800"><span>{{tr('نام','Name')}}</span><span>Endpoint</span><span>{{tr('رویدادها','Events')}}</span><span>{{tr('وضعیت','Status')}}</span><span>{{tr('عملیات','Actions')}}</span></div><article v-for="h in hooks" :key="h.id" class="grid gap-3 border-b p-5 last:border-0 md:grid-cols-[1fr_1.5fr_1fr_.7fr_auto] md:items-center"><div class="flex items-center gap-2 font-bold"><Webhook :size="17" class="text-brand-600"/>{{h.name}}</div><code class="truncate text-xs text-slate-400" dir="ltr">{{h.url}}</code><span class="truncate text-xs">{{h.events.join(', ')}}</span><button class="badge w-fit" :class="h.status==='ACTIVE'?'bg-emerald-50 text-emerald-600':'bg-slate-100 text-slate-500'" @click="toggle(h)">{{h.status}}</button><div class="flex gap-1"><button class="icon-btn" :title="tr('تاریخچه','History')" @click="showDeliveries(h.id)"><Eye :size="16"/></button><button class="icon-btn" :disabled="busy" :title="tr('ارسال تست','Send test')" @click="test(h.id)"><Play :size="16"/></button><button class="icon-btn hover:text-red-500" :title="tr('حذف','Delete')" @click="remove(h.id)"><Trash2 :size="16"/></button></div></article></template></section><AppModal :open="modal" :title="tr('ایجاد وب‌هوک','Create webhook')" @close="modal=false"><form class="space-y-4" @submit.prevent="create"><label class="block"><span class="label">{{tr('نام','Name')}}</span><input v-model="form.name" class="input" required minlength="2"></label><label class="block"><span class="label">Endpoint URL</span><input v-model="form.url" class="input" type="url" required dir="ltr"></label><fieldset><legend class="label">{{tr('رویدادها','Events')}}</legend><label v-for="e in eventOptions" :key="e" class="mb-2 flex gap-2 text-sm"><input v-model="form.events" type="checkbox" :value="e" class="accent-brand-600">{{e}}</label></fieldset><button class="btn btn-primary w-full" :disabled="busy||!form.events.length"><LoaderCircle v-if="busy" class="animate-spin" :size="17"/>{{tr('ایجاد وب‌هوک','Create webhook')}}</button></form></AppModal><AppModal :open="detail" :title="tr('تاریخچه تحویل','Delivery history')" @close="detail=false"><div v-if="!deliveries.length" class="muted text-center">{{tr('هنوز ارسالی ثبت نشده است.','No deliveries yet.')}}</div><div v-for="d in deliveries" :key="d.id" class="mb-3 rounded-xl border p-3 text-xs"><div class="flex justify-between"><b>{{d.event}}</b><span :class="d.httpStatus>=200&&d.httpStatus<300?'text-emerald-600':'text-red-500'">HTTP {{d.httpStatus||'—'}}</span></div><p class="mt-2 text-slate-400">{{d.durationMs}}ms · {{new Date(d.createdAt).toLocaleString()}}</p><pre class="mt-2 max-h-24 overflow-auto rounded bg-slate-950 p-2 text-left text-slate-200" dir="ltr">{{d.responseBody||'—'}}</pre></div></AppModal></div></template>
